import {transact} from './core.js';
import * as T from '../vendor/three.module.js';
import {heightAt,WATER} from './data.js';
import {SURFACE_REGIONS,SURFACE_ROADS,SURFACE_TILE,distanceToRoad,surfaceRegionAt} from './surface-data.js';
export function sampleSurfaceHeight(x,z){if(Math.max(Math.abs(x),Math.abs(z))<=205)return heightAt(x,z);const size=Math.max(Math.abs(x),Math.abs(z))<400?4:16,ax=Math.floor(x/size)*size,az=Math.floor(z/size)*size,u=(x-ax)/size,v=(z-az)/size,h=[heightAt(ax,az),heightAt(ax+size,az),heightAt(ax+size,az+size),heightAt(ax,az+size)];return u>=v?h[0]+u*(h[1]-h[0])+v*(h[2]-h[1]):h[0]+v*(h[3]-h[0])+u*(h[2]-h[3]);}
const roadColor=new T.Color(0xc2ae7d);
export class SurfaceWorld{
 constructor(g){this.g=g;this.group=new T.Group();g.world.root.add(this.group);this.tiles=new Map();this.queue=[];this.outposts=[];this.uniforms={center:{value:new T.Vector2()},radius:{value:0}};this.buildMaterials();this.buildBackground();this.buildRoads();this.buildWater();this.buildOutposts();this.buildMount();g.world.surfaceHeightAt=sampleSurfaceHeight;this.mapBase=this.buildMapBase();}
 buildMaterials(){const mask=(material,background)=>{material.onBeforeCompile=shader=>{shader.uniforms.surfaceCenter=this.uniforms.center;shader.uniforms.surfaceRadius=this.uniforms.radius;shader.vertexShader='varying vec3 vSurfaceWorld;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <project_vertex>','vSurfaceWorld=(modelMatrix*vec4(transformed,1.)).xyz;\n#include <project_vertex>');shader.fragmentShader='varying vec3 vSurfaceWorld;uniform vec2 surfaceCenter;uniform float surfaceRadius;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <clipping_planes_fragment>',background?'#include <clipping_planes_fragment>\nif(max(abs(vSurfaceWorld.x),abs(vSurfaceWorld.z))<205.||max(abs(vSurfaceWorld.x-surfaceCenter.x),abs(vSurfaceWorld.z-surfaceCenter.y))<surfaceRadius)discard;':'#include <clipping_planes_fragment>\nif(max(abs(vSurfaceWorld.x),abs(vSurfaceWorld.z))<205.)discard;');};material.customProgramCacheKey=()=>background?'surface-background-1':'surface-near-1';return material;};this.material=mask(new T.MeshStandardMaterial({vertexColors:true,roughness:.96}),false);this.backgroundMaterial=mask(new T.MeshStandardMaterial({vertexColors:true,roughness:1}),true);}
 colorAt(x,z,h){const r=surfaceRegionAt(x,z),c=new T.Color(r.color);if(h>330)c.lerp(new T.Color(0xe1e5df),Math.min(1,(h-330)/180));else if(h<4)c.set(0x8d9c80);if(distanceToRoad(x,z)<9)c.copy(roadColor);return c.multiplyScalar(.96+.04*Math.sin(x*.02+z*.01));}
 geometry(x,z,size,segments){const positions=[],colors=[],indices=[];for(let j=0;j<=segments;j++)for(let i=0;i<=segments;i++){const px=x+i*size/segments,pz=z+j*size/segments,h=heightAt(px,pz),c=this.colorAt(px,pz,h);positions.push(px,h,pz);colors.push(c.r,c.g,c.b);}for(let j=0;j<segments;j++)for(let i=0;i<segments;i++){const a=j*(segments+1)+i,b=a+1,c=a+segments+1,d=c+1;indices.push(a,c,b,b,c,d);}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));geo.setIndex(indices);geo.computeVertexNormals();geo.computeBoundingSphere();return geo;}
 buildBackground(){const positions=[],colors=[],indices=[],nx=80,nz=68;for(let j=0;j<=nz;j++)for(let i=0;i<=nx;i++){const x=-6000+i*150,z=-5000+j*10000/nz,h=heightAt(x,z),c=this.colorAt(x,z,h);positions.push(x,h,z);colors.push(c.r,c.g,c.b);}for(let j=0;j<nz;j++)for(let i=0;i<nx;i++){const a=j*(nx+1)+i,b=a+1,c=a+nx+1;indices.push(a,c,b,b,c,c+1);}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));geo.setIndex(indices);geo.computeVertexNormals();this.background=new T.Mesh(geo,this.backgroundMaterial);this.background.receiveShadow=false;this.group.add(this.background);}
 buildRoads(){for(const {a,b}of SURFACE_ROADS){const n=Math.ceil(Math.hypot(b.x-a.x,b.z-a.z)/24),length=Math.hypot(b.x-a.x,b.z-a.z),rx=-(b.z-a.z)/length*5,rz=(b.x-a.x)/length*5,v=[],ids=[];for(let i=0;i<=n;i++){const t=i/n,x=a.x+(b.x-a.x)*t,z=a.z+(b.z-a.z)*t;for(const side of [-1,1]){const px=x+rx*side,pz=z+rz*side;v.push(px,sampleSurfaceHeight(px,pz)+.06,pz);}if(i<n&&Math.max(Math.abs(x),Math.abs(z))>230){const k=i*2;ids.push(k,k+2,k+1,k+1,k+2,k+3);}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(v,3));geo.setIndex(ids);geo.computeVertexNormals();const road=new T.Mesh(geo,new T.MeshStandardMaterial({color:0xc5b188,roughness:1,side:T.DoubleSide}));road.receiveShadow=true;this.group.add(road);}}
 buildWater(){const mat=new T.MeshStandardMaterial({color:0x739fa0,roughness:.25,metalness:.2,side:T.DoubleSide});mat.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 vWaterWorld;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <project_vertex>','vWaterWorld=(modelMatrix*vec4(transformed,1.)).xyz;\n#include <project_vertex>');shader.fragmentShader='varying vec3 vWaterWorld;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <clipping_planes_fragment>','#include <clipping_planes_fragment>\nif(max(abs(vWaterWorld.x),abs(vWaterWorld.z))<205.)discard;');};const water=new T.Mesh(new T.PlaneGeometry(12000,10000),mat);water.rotation.x=-Math.PI/2;water.position.y=WATER-.015;water.receiveShadow=true;this.group.add(water);}
 buildTile(ix,iz,near){const x=ix*400,z=iz*400,group=new T.Group(),mesh=new T.Mesh(this.geometry(x,z,400,near?(ix>=-1&&ix<=0&&iz>=-1&&iz<=0?100:25):8),this.material);mesh.receiveShadow=true;group.add(mesh);if(near){let seed=(ix*7919+iz*104729+9137)>>>0;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},points=[];const r=surfaceRegionAt(x+200,z+200);for(let i=0;i<24;i++){const px=x+rand()*400,pz=z+rand()*400,h=sampleSurfaceHeight(px,pz);if(Math.max(Math.abs(px),Math.abs(pz))<230||h<WATER+1||h>340||r.id==='gerudo'||r.id==='eldin'||distanceToRoad(px,pz)<20||SURFACE_REGIONS.some(r=>Math.hypot(r.x-px,r.z-pz)<65))continue;points.push({x:px,z:pz,h});}group.userData.colliders=points.map(p=>({x:p.x,z:p.z,r:.5,bottom:p.h-.1,top:p.h+8}));if(points.length){const trunk=new T.InstancedMesh(this.g.world.geos.cylinder,this.g.world.material(0x626d57),points.length),leaf=new T.InstancedMesh(this.g.world.geos.sphere,this.g.world.material(r.id==='akkala'?0xc29c5a:r.id==='faron'?0x67946a:0x8ca06b),points.length),d=new T.Object3D();points.forEach((p,i)=>{d.position.set(p.x,p.h+3,p.z);d.scale.set(.4,6,.4);d.updateMatrix();trunk.setMatrixAt(i,d.matrix);d.position.set(p.x,p.h+7,p.z);d.scale.set(4,2.7,3.7);d.updateMatrix();leaf.setMatrixAt(i,d.matrix);});trunk.castShadow=leaf.castShadow=true;group.add(trunk,leaf);}}this.group.add(group);this.tiles.set(ix+','+iz,{group,near,colliders:group.userData.colliders||[]});}
 update(dt){const g=this.g;if(g.state.journey.stage!=='hub')return;const p=g.player.pos,cx=Math.floor(p.x/400),cz=Math.floor(p.z/400),key=cx+','+cz;if(this.center!==key){this.center=key;this.uniforms.center.value.set(cx*400+200,cz*400+200);const wanted=new Set(),queue=[];for(let z=-4;z<=4;z++)for(let x=-4;x<=4;x++){const ix=cx+x,iz=cz+z;if(ix< -15||ix>=15||iz< -13||iz>=13)continue;const id=ix+','+iz,near=Math.abs(x)<=2&&Math.abs(z)<=2;wanted.add(id);const old=this.tiles.get(id);if(old&&old.near!==near){this.removeTile(id);queue.push({ix,iz,near,d:Math.max(Math.abs(x),Math.abs(z))});}else if(!old)queue.push({ix,iz,near,d:Math.max(Math.abs(x),Math.abs(z))});}for(const id of this.tiles.keys())if(!wanted.has(id))this.removeTile(id);this.queue=queue.sort((a,b)=>a.d-b.d);}
  for(let i=0;i<2&&this.queue.length;i++){const q=this.queue.shift();this.buildTile(q.ix,q.iz,q.near);}this.uniforms.radius.value=this.queue.length?0:1800;
  for(const post of this.outposts)post.group.visible=Math.hypot(post.x-p.x,post.z-p.z)<1400;
  this.syncPuzzles();if(this.ventMotes){this.ventMotes.visible=g.state.surface.solved.includes('eldin-vent')&&Math.hypot(p.x-2068,p.z+2532)<1200;if(this.ventMotes.visible){const a=this.ventMotes.geometry.attributes.position;for(let i=0;i<64;i++){const y=(g.elapsed*6+i)%64;a.setXYZ(i,Math.sin(i*2.4+g.elapsed)*(.8+y*.1),y,Math.cos(i*2.4+g.elapsed)*(.8+y*.1));}a.needsUpdate=true;}}const mount=g.state.surface.mount;this.mount.position.set(mount.x,mount.y+.35,mount.z);this.mount.visible=Math.hypot(mount.x-p.x,mount.z-p.z)<300;for(const e of g.enemies||[])e.mesh.visible=e.hp>0&&Math.hypot(e.x-p.x,e.z-p.z)<250;
 }
 removeTile(id){const t=this.tiles.get(id);if(!t)return;t.group.traverse(m=>{if(m.isMesh&&!m.isInstancedMesh)m.geometry.dispose();if(m.isInstancedMesh)m.dispose();});t.group.removeFromParent();this.tiles.delete(id);}
 objective(){const s=this.g.state;return s.journey.stage==='hub'&&s.journey.glider&&(Math.max(Math.abs(this.g.player.pos.x),Math.abs(this.g.player.pos.z))>230||s.facts.rewarded)?'Survey the lower lands · '+s.surface.visited.length+' / 8 outposts recorded':null;}
 regionName(){return surfaceRegionAt(this.g.player.pos.x,this.g.player.pos.z).name;}
 initialize(){this.center=null;this.queue=[];this.update(0);}
 buildOutposts(){const g=this.g,w=g.world;for(const r of SURFACE_REGIONS){const y=sampleSurfaceHeight(r.x,r.z),group=new T.Group();group.position.set(r.x,y,r.z);this.group.add(group);const m=(kind,c,x,h,z,sx,sy,sz,e=0)=>w.mesh(kind,c,group,x,h,z,sx,sy,sz,e);m('cylinder',0x81917a,0,.15,0,10,.3,10);for(const x of [-4,4]){m('cylinder',0xb6bd9a,x,2.5,-3,.25,5,.25);m('box',0x8a7861,x,1,3,.3,2,.3);}const roof=m('box',r.id==='gerudo'?0xcbaf7f:r.id==='hebra'?0xcfd7cb:0x6f9b8c,0,5,-2,10,.3,8);roof.rotation.z=.08;m('box',0xae8b58,-3,.8,1,2,1.6,1.5);m('ring',0xa9ddbe,0,2,4,1.1,1.1,1.1,.4);const keeper=w.makeHuman(r.id==='hebra'?0xb8c4bd:0x62887b,0xb38b57);keeper.position.set(2,0,0);group.add(keeper);g.world.interactables.push({id:'surface-post-'+r.id,type:'surface-post',x:r.x+2,y,z:r.z,r:4,label:r.name+' expedition outpost',region:r.id});this.outposts.push({...r,y,group});}
  this.mirrors=[];const desert=SURFACE_REGIONS.find(r=>r.id==='gerudo');for(let i=0;i<3;i++){const x=desert.x-8+i*8,z=desert.z+24,y=sampleSurfaceHeight(x,z);const mirror=w.mesh('box',0xc7d8bf,this.group,x,y+1.6,z,2.4,2.4,.12);w.mesh('cylinder',0x9a865b,this.group,x,y+.8,z,.2,1.6,.2);const line=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3(x,y+1.6,z),new T.Vector3(x,y+1.6,z-12)]),new T.LineBasicMaterial({color:0xffdc99}));this.group.add(line);mirror.userData.beam=line;const target=[1,3,2][i]*Math.PI/2;w.mesh('sphere',0xd9ca8c,this.group,x+Math.sin(target)*12,y+1.6,z-Math.cos(target)*12,.5,.65,.5,.3);this.mirrors.push(mirror);w.interactables.push({id:'surface-mirror-'+i,type:'surface-mirror',index:i,x,y,z,r:3,label:'Turn the desert signal mirror '+(i+1)});}
  for(const [id,region,dx,dz,type,label]of [['lanayru-filter','lanayru',18,18,'surface-filter','Repair the river filter · 1 mossglass'],['eldin-vent','eldin',18,18,'surface-vent','Open the geothermal wind vent']]){const r=SURFACE_REGIONS.find(r=>r.id===region),x=r.x+dx,z=r.z+dz,y=sampleSurfaceHeight(x,z);w.mesh('cylinder',0xa7bbae,this.group,x,y+.7,z,2,1.4,2);w.mesh('ring',0x83d9bf,this.group,x,y+1.7,z,1,1,1,.4);if(id==='eldin-vent'){const points=[];for(let i=0;i<64;i++)points.push(Math.sin(i*2.4)*6,i,Math.cos(i*2.4)*6);const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(points,3));this.ventMotes=new T.Points(geo,new T.PointsMaterial({color:0xc6e5ca,size:.35,transparent:true,opacity:.8,depthWrite:false}));this.ventMotes.position.set(x,y,z);this.ventMotes.frustumCulled=false;this.group.add(this.ventMotes);}if(id==='lanayru-filter'){this.filterWater=w.mesh('cylinder',0x817a4f,this.group,x,y+1.45,z,1.7,.08,1.7);this.filterWater.material=this.filterWater.material.clone();const supply=w.mesh('sphere',0x8dded0,this.group,x+6,y+.6,z,.4,.8,.4,.3);w.pickupMeshes.set('surface-filter-supply',supply);w.interactables.push({id:'surface-filter-supply',type:'pickup',x:x+6,y,z,r:2.8,label:'Take the spare filtration prism',data:{id:'surface-filter-supply',kind:'glass',count:1}});}w.interactables.push({id,type,x,y,z,r:3,label});}
 }
 buildMount(){const w=this.g.world;this.mount=new T.Group();this.group.add(this.mount);w.mesh('box',0xb39a66,this.mount,0,.1,0,2,.45,3);for(const x of [-1,1])for(const z of [-1,1]){const wheel=w.mesh('cylinder',0x58695c,this.mount,x,0,z,.4,.28,.4);wheel.rotation.z=Math.PI/2;}w.mesh('box',0x5f8d80,this.mount,0,.6,.3,1.2,.7,1);w.mesh('cylinder',0xa5d7ba,this.mount,0,1.1,-1,.06,1.2,.06);}
 drive(dt,axis){const g=this.g,p=g.state.surface.mount,moving=Math.hypot(axis.x,axis.z)>0,speed=(g.settings.sprintToggle?g.player.sprintOn:g.input.down('sprint'))?26:17,nx=Math.max(-5990,Math.min(5990,p.x+axis.x*dt*speed)),nz=Math.max(-4990,Math.min(4990,p.z+axis.z*dt*speed)),h=sampleSurfaceHeight(nx,nz);if(h>WATER+.3&&h-p.y<Math.max(.7,dt*speed*.8)&&p.y-h<3&&!g.world.obstacleAt(nx,nz,h)){p.x=nx;p.z=nz;p.y=h;}if(moving)this.mount.rotation.y=Math.atan2(axis.x,axis.z);g.player.pos.set(p.x,p.y+.65,p.z);g.player.vel.set(0,0,0);g.player.grounded=true;g.player.gliding=false;}
 obstacleAt(x,z,y){const ix=Math.floor(x/400),iz=Math.floor(z/400);for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++){const t=this.tiles.get((ix+dx)+','+(iz+dz));const c=t?.colliders.find(c=>y>=c.bottom&&y<c.top-.3&&Math.hypot(x-c.x,z-c.z)<c.r+.38);if(c)return c;}return null;}
 syncPuzzles(){const s=this.g.state.surface;for(let i=0;i<this.mirrors.length;i++){const m=this.mirrors[i],a=s.mirrors[i]*Math.PI/2;if(m.userData.lastAngle===a)continue;m.userData.lastAngle=a;m.rotation.y=a;const p=m.userData.beam.geometry.attributes.position;p.setXYZ(1,m.position.x+Math.sin(a)*12,m.position.y,m.position.z-Math.cos(a)*12);p.needsUpdate=true;m.userData.beam.geometry.computeBoundingSphere();m.userData.beam.material.color.set(s.mirrors[i]===[1,3,2][i]?0xa5ebc9:0xe2bc83);}if(this.filterWater)this.filterWater.material.color.set(s.solved.includes('lanayru-filter')?0x7ac5bd:0x817a4f);}
 interact(o){const g=this.g,s=g.state.surface;if(!o.type?.startsWith('surface-'))return false;
  if(o.type==='surface-mount'){g.player.riding='surface-skimmer';g.player.gliding=false;g.toast('Survey skimmer · movement steers · sprint boosts · jump dismounts');return true;}
  if(o.type==='surface-post'){const r=SURFACE_REGIONS.find(r=>r.id===o.region);if(!s.visited.includes(r.id)){if(!transact(g.state.inventory,{copper:2,fiber:2})){g.toast('Make room for the outpost supplies first.');return true;}s.visited.push(r.id);if(s.visited.length===8&&!s.solved.includes('regional-survey')){s.solved.push('regional-survey');g.state.player.maxStamina=Math.min(200,g.state.player.maxStamina+20);g.state.player.stamina=g.state.player.maxStamina;}g.audio.play('discover');g.save(false);}
   const note=r.id==='gerudo'?'The three mirrors must point east, west, then south. The receiver stones mark those directions.':r.id==='lanayru'?'Fit one mossglass to the river filter. A spare prism is kept beside the tank.':r.id==='eldin'?'The geothermal vent can supply an updraft once its regulator is opened. Use a sailcloth above it.':'The marked roads lead to the other survey outposts. Keep the skimmer on dry ground; its wheels will stop at deep water.';
   g.ui.talk([[r.name+' outpost','Surface survey · '+s.visited.length+' / 8'],[r.subtitle+'. '+note,'A bedroll, supplies and the survey skimmer are available here. Every recorded outpost can be reached again from your field map.']],choice=>{if(choice==='rest'){g.state.player.hp=g.state.player.maxHp;g.state.player.stamina=g.state.player.maxStamina;g.state.safe={x:r.x+5,y:sampleSurfaceHeight(r.x+5,r.z+5),z:r.z+5};g.save(false);g.toast('Rested at '+r.name+'.');}else if(choice==='mount'){Object.assign(s.mount,{x:r.x+12,y:sampleSurfaceHeight(r.x+12,r.z+6),z:r.z+6});g.save(false);g.toast('The survey skimmer is ready beside the shelter.');}else g.ui.openBook('map');},[{id:'rest',title:'Rest at the outpost',desc:'Recover health and stamina.'},{id:'mount',title:'Call the survey skimmer',desc:'Recover the vehicle beside this shelter.'},{id:'map',title:'Review recorded routes',desc:'Travel to discovered outposts.'}]);return true;}
  if(o.type==='surface-mirror'){s.mirrors[o.index]=(s.mirrors[o.index]+1)%4;this.syncPuzzles();if(s.mirrors.every((n,i)=>n===[1,3,2][i])&&!s.solved.includes('gerudo-light')){if(transact(g.state.inventory,{glass:2,broth:2})){s.solved.push('gerudo-light');g.state.player.maxStamina=Math.min(200,g.state.player.maxStamina+10);g.state.player.stamina=g.state.player.maxStamina;g.toast('Desert signal restored · +10 stamina capacity · field supplies');g.audio.play('discover');}else g.toast('The mirrors are aligned. Make room for supplies, then turn the last mirror through one cycle.');}else g.toast('Mirror '+(o.index+1)+' faces '+['north','east','south','west'][s.mirrors[o.index]]+'.');g.save(false);return true;}
  if(o.type==='surface-filter'||o.type==='surface-vent'){const id=o.type==='surface-filter'?'lanayru-filter':'eldin-vent';if(s.solved.includes(id)){g.toast(id==='eldin-vent'?'The geothermal updraft is active above the vent.':'The filtration tank runs clear.');return true;}const delta=id==='lanayru-filter'?{glass:-1,broth:2}:{copper:3,fiber:3};if(!transact(g.state.inventory,delta)){g.toast(id==='lanayru-filter'?'A mossglass prism is required. Check the spare beside the tank.':'Make room for the recovered materials.');return true;}s.solved.push(id);g.audio.play('discover');this.syncPuzzles();g.save(false);g.toast(id==='eldin-vent'?'Vent opened · a warm updraft rises beside the outpost.':'Filtration restored · clean tank · 2 broth');return true;}
  return true;
 }
 travel(id){const g=this.g,r=SURFACE_REGIONS.find(r=>r.id===id);if(!r||!g.state.surface.visited.includes(id)||g.state.journey.stage!=='hub'){g.toast('Record this outpost before using its route.');return;}if(g.enemies.some(e=>e.hp>0&&e.alert&&Math.hypot(e.x-g.player.pos.x,e.z-g.player.pos.z)<25)){g.toast('Find quiet ground before traveling.');return;}g.journey.cancelFlight();g.echo.cancel();g.rise.cancel();g.releaseHeld(false);g.player.riding=null;const p={x:r.x+5,y:sampleSurfaceHeight(r.x+5,r.z+5),z:r.z+5};Object.assign(g.state.player,p);g.state.safe={...p};g.player.load(g.state);g.ui.play();this.initialize();g.save(false);g.toast('Arrived at '+r.name+' outpost.');}
 buildMapBase(){let out='';for(let z=0;z<64;z++)for(let x=0;x<76;x++){const wx=-6000+x*160,wz=-5000+z*160,h=heightAt(wx,wz),c=h<WATER?new T.Color(0x739fa0):this.colorAt(wx,wz,h);out+=`<rect x="${wx}" y="${wz}" width="162" height="162" fill="#${c.getHexString()}"/>`;}return out;}
 mapSVG(p){return `<svg class="worldmap" viewBox="-6100 -5100 12200 10200" role="img" aria-label="Expanded surface expedition map">${this.mapBase}${SURFACE_ROADS.map(({a,b})=>`<path d="M${a.x} ${a.z}L${b.x} ${b.z}" stroke="#e0c48e" stroke-width="24" fill="none"/>`).join('')}${SURFACE_REGIONS.map(r=>`<g transform="translate(${r.x},${r.z})"><circle r="45" fill="#ead7a2"/><text y="-100" text-anchor="middle" font-size="150" fill="#f7edcf" stroke="#3c5d48" stroke-width="12" paint-order="stroke">${r.name}</text></g>`).join('')}<circle cx="${p.x}" cy="${p.z}" r="60" fill="#6f432b"/></svg>`;}
 drawMini(ctx,p){ctx.clearRect(0,0,264,264);for(let z=0;z<22;z++)for(let x=0;x<22;x++){const wx=p.x+(x-11)*55,wz=p.z+(z-11)*55,h=heightAt(wx,wz);ctx.fillStyle=h<WATER?'#75a6a6':'#'+this.colorAt(wx,wz,h).getHexString();ctx.fillRect(x*12,z*12,12.2,12.2);}ctx.fillStyle='#fff0be';ctx.beginPath();ctx.arc(132,132,4,0,7);ctx.fill();}
}
